package org.apache.commons.jxpath.ri;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NamespaceResolver.seal()
 */
public class NamespaceResolver_seal_TriageGen1Test {

    /**
     * Tests that seal() sets the sealed flag to true when there is no parent.
     * This covers the case where (parent == null).
     */
    @Test
    public void testSealNoParent() {
        NamespaceResolver resolver = new NamespaceResolver();
        assertFalse("Resolver should not be sealed initially", resolver.isSealed());

        resolver.seal();

        assertTrue("Resolver should be sealed after calling seal()", resolver.isSealed());
    }

    /**
     * Tests that seal() sets the sealed flag to true for the current object 
     * and recursively calls seal() on the parent.
     * This covers the case where (parent != null) and the recursive branch.
     */
    @Test
    public void testSealWithParent() {
        NamespaceResolver parent = new NamespaceResolver();
        NamespaceResolver child = new NamespaceResolver(parent);

        assertFalse("Parent should not be sealed initially", parent.isSealed());
        assertFalse("Child should not be sealed initially", child.isSealed());

        child.seal();

        assertTrue("Child should be sealed after calling seal()", child.isSealed());
        assertTrue("Parent should be sealed via recursion", parent.isSealed());
    }

    /**
     * Tests a chain of multiple parents to ensure deep recursion works correctly.
     */
    @Test
    public void testSealDeepHierarchy() {
        NamespaceResolver root = new NamespaceResolver();
        NamespaceResolver middle = new NamespaceResolver(root);
        NamespaceResolver leaf = new NamespaceResolver(middle);

        leaf.seal();

        assertTrue("Leaf should be sealed", leaf.isSealed());
        assertTrue("Middle should be sealed", middle.isSealed());
        assertTrue("Root should be sealed", root.isSealed());
    }

    /**
     * Tests that calling seal() multiple times does not cause issues.
     */
    @Test
    public void testSealIdempotency() {
        NamespaceResolver resolver = new NamespaceResolver();
        resolver.seal();
        assertTrue(resolver.isSealed());

        // Calling it again should not throw exception or change state
        resolver.seal();
        assertTrue(resolver.isSealed());
    }
}
